WITH valid AS (SELECT id, name, country, city, segment, signup_date, credit_limit, age, ADD_MONTHS(signup_date, 3) AS signup_date_plus_months, credit_limit - age AS credit_limit_minus_age, COALESCE(segment, 'DIRECT') AS segment_filled FROM customers WHERE segment IS DISTINCT FROM 'Corporate' AND signup_date > DATE '2023-09-01') SELECT id, name, country, city, signup_date, age, credit_limit_minus_age, LEAD(credit_limit) OVER (PARTITION BY city, segment ORDER BY age ASC, id ASC) AS next_credit_limit, LEAD(credit_limit_minus_age) OVER (PARTITION BY city, segment ORDER BY age ASC, id ASC) AS next_credit_limit_minus_age, ROW_NUMBER() OVER (PARTITION BY city, segment ORDER BY age ASC, id ASC) AS event_seq, SUM(credit_limit) OVER (PARTITION BY segment) AS segment_sum_credit_limit FROM valid;
